// Diagnostic accuracy of a binary test from its 2 x 2 table (epiR's epi.tests): sensitivity, specificity, predictive
// values, likelihood ratios, accuracy, the diagnostic odds ratio and the prevalences, with intervals.
//
// Written for rStats.js from oracle/roc-behaviour.md, section 9 (no ported code; the source of epiR was not read):
// - The proportions' intervals are binomCI's: Clopper-Pearson ("exact"; Clopper and Pearson, Biometrika 26, 1934,
//   computed with qbeta directly, where epiR's 1 - qbeta(...) loses digits), Wilson's (Wilson, JASA 22, 1927) and
//   Jeffreys' (Brown, Cai and DasGupta, Statistical Science 16, 2001).
// - The likelihood ratios' intervals: the log method of Simel, Samsa and Matchar (J Clin Epidemiol 44, 1991), with
//   the variance of log LR+ written as c/(a M1) + d/(b M0) (= 1/a - 1/M1 + 1/b - 1/M0, without the cancellation).
// - The diagnostic odds ratio's interval: Woolf's (Annals of Human Genetics 19, 1955), exp(log OR -+ z sqrt(1/a + 1/b
//   + 1/c + 1/d)).
// - Predictive values at a given prevalence p by Bayes' theorem: se p/(se p + (1 - sp)(1 - p)) and sp (1 - p)/(sp (1 -
//   p) + (1 - se) p), from the counts (1 - sp = b/M0 and 1 - se = c/M1 without cancellation).
// Zero cells give what the formulas give (Inf, 0 and NaN limits), as epiR; no correction is added.
import { qnorm } from "../distributions/normal.js";
import { reported, unreported } from "../internal/warnings.js";
import { binomCI } from "./binomCI.js";
import { matchChoice } from "./power.js";
import { ratioToDouble } from "./roc.js";
import { checkConfLevelOpen, isCount } from "./types.js";
// Generated by `node scripts/option-keys.mjs --write` from the option types; do not edit (begin)
import { checkOptions } from "../internal/checkOptions.js";
const DIAGNOSTIC_TESTS_KEYS = ["method", "confLevel", "prevalence"];
/**
 * Sensitivity, specificity, predictive values, likelihood ratios, accuracy, the diagnostic odds ratio and the true and
 * apparent prevalence of a binary test, each with a confidence interval, from its 2 × 2 table. Equivalent to
 * `epiR::epi.tests()` in R.
 *
 * The table is epiR's: rows test positive and negative, columns disease present and absent, `[[a, b], [c, d]]` with
 * a the true positives, b the false positives, c the false negatives and d the true negatives. The proportions'
 * intervals are those of {@link binomCI}: `"exact"` is Clopper-Pearson's, computed directly (epiR computes it as 1 −
 * qbeta(...), which loses digits for small limits); `"jeffreys"` gives 0 and 1 at the ends, as binomCI (epiR the
 * beta quantiles). The likelihood ratios have the log interval (Simel, Samsa and Matchar 1991) and the odds ratio
 * Woolf's. Zero cells give infinite ratios and NaN limits, as epiR; a zero row or column total is an error.
 *
 * @param table The 2 × 2 table of counts (an array of two rows).
 * @param options See {@link DiagnosticTestsOptions}.
 *
 * @example
 * ```ts
 * const r = diagnosticTests([[670, 202], [74, 640]]);
 * r.sensitivity.estimate; // 0.9005376344086021
 * r.sensitivity.confInt;  // [0.8767461767957109, 0.9210922995836943]
 * r.lrPos.estimate;       // 3.7537261790695196
 * diagnosticTests([[670, 202], [74, 640]], { prevalence: 0.1 }).ppvAtPrevalence; // 0.2943238804381625
 * ```
 *
 * @category Hypothesis tests
 */
export function diagnosticTests(table, options = {}) {
    checkOptions(options, DIAGNOSTIC_TESTS_KEYS, "diagnosticTests"); // generated: option-keys.mjs
    const method = matchChoice(options.method, ["exact", "wilson", "jeffreys"]);
    const confLevel = options.confLevel ?? 0.95;
    checkConfLevelOpen(confLevel);
    if (!Array.isArray(table) || table.length !== 2 || table.some((r) => !(Array.isArray(r) || ArrayBuffer.isView(r)) || r.length !== 2)) {
        throw new TypeError("'table' must be a 2 x 2 table (an array of two rows of two counts)");
    }
    const cells = [table[0][0], table[0][1], table[1][0], table[1][1]];
    if (cells.some((v) => typeof v !== "number"))
        throw new TypeError("the counts must be numbers");
    if (!cells.every(isCount))
        throw new RangeError("the counts must be nonnegative integers");
    const [a, b, c, d] = cells.map(Math.round);
    const M1 = a + c;
    const M0 = b + d;
    const N1 = a + b;
    const N0 = c + d;
    const total = M1 + M0;
    if (M1 === 0 || M0 === 0 || N1 === 0 || N0 === 0)
        throw new RangeError("every row and column total of the table must be positive");
    const prop = (x, n) => {
        const r = unreported(() => binomCI(x, n, { method: method === "exact" ? "clopper-pearson" : method, confLevel }));
        return { estimate: r.estimate, confInt: r.confInt };
    };
    const alpha = 1 - confLevel;
    const z = alpha / 2 < 1e-8 ? qnorm(alpha / 2, { lowerTail: false }) : qnorm(1 - alpha / 2);
    const logInterval = (est, v) => {
        const half = z * Math.sqrt(v);
        return { estimate: est, confInt: [Math.exp(Math.log(est) - half), Math.exp(Math.log(est) + half)] };
    };
    const se = a / M1;
    const sp = d / M0;
    const result = {
        sensitivity: prop(a, M1),
        specificity: prop(d, M0),
        ppv: prop(a, N1),
        npv: prop(d, N0),
        // se/(1 - sp) with 1 - sp = b/M0, and (1 - se)/sp with 1 - se = c/M1, each from the counts and rounded once:
        // (a M0)/(M1 b) (se / (b / M0) was rounded three times); b = 0 gives Inf, or NaN for a = 0
        lrPos: logInterval(b === 0 ? se / 0 : ratioToDouble(BigInt(a) * BigInt(M0), BigInt(M1) * BigInt(b)), c / (a * M1) + d / (b * M0)),
        // (c M0)/(M1 d), rounded once (c / M1 / sp was rounded three times); d = 0 gives Inf or NaN
        lrNeg: logInterval(d === 0 ? c / M1 / sp : ratioToDouble(BigInt(c) * BigInt(M0), BigInt(M1) * BigInt(d)), a / (c * M1) + b / (d * M0)),
        accuracy: prop(a + d, total),
        diagnosticOR: logInterval((a * d) / (b * c), 1 / a + 1 / b + 1 / c + 1 / d),
        prevalence: prop(M1, total),
        apparentPrevalence: prop(N1, total),
        method,
        confLevel,
        warnings: [],
    };
    if (options.prevalence !== undefined) {
        const p = options.prevalence;
        if (!(typeof p === "number" && p > 0 && p < 1))
            throw new RangeError("'prevalence' must be a number in (0, 1)");
        // p and 1 - p scaled by 2^600 in the positive predictive value when p is tiny: se p underflowed (to 0, and 0/0
        // for b = 0, at p = 5e-324), and the ratio is unchanged by a common power of 2
        const scale = p < 2 ** -500 ? 2 ** 600 : 1;
        const tpr = se * (p * scale);
        const fpr = (b / M0) * ((1 - p) * scale);
        const tnr = sp * (1 - p);
        const fnr = (c / M1) * p;
        result.ppvAtPrevalence = tpr / (tpr + fpr);
        result.npvAtPrevalence = tnr / (tnr + fnr);
    }
    return reported("diagnosticTests", result);
}
